function sliderProductMain() {
    var swiper = new Swiper(".product-main__slider .mySwiper", {
        slidesPerView: "auto",
        spaceBetween: 12,
        freeMode: true,
        watchSlidesProgress: true,
        direction: "vertical",
        breakpoints: {
            320: {
                direction: "horizontal",
            },
            577: {
                direction: "vertical",
            }
        }
    });
    var swiper2 = new Swiper(".product-main__slider .mySwiper2", {
        spaceBetween: 12,
        slidesPerView: 1,
        thumbs: {
            swiper: swiper,
        },
    });
}

$(document).ready(function () {
    sliderProductMain();

    // Menu
    $('.burger').click(function () {
        $(this).toggleClass('burger--active')
        $('.header__menu').toggleClass('header__menu--active')
        $('body').toggleClass('fixed-body')
    })

    // Search
    $('.header__search-btn').click(function () {
        $(this).parents('.header__inner').addClass('search--active')
    })

    $('.header__search-close').click(function () {
        $(this).parents('.header__inner').removeClass('search--active')
        $('.header__search input').val('').trigger('input');
    })

    // Radio
    $('.filter__checkbox input[type="radio"]').on('mousedown', function () {
        $(this).data('wasChecked', $(this).prop('checked'));
    });

    $('.filter__checkbox input[type="radio"]').on('click', function () {
        if ($(this).data('wasChecked')) {
            $(this).prop('checked', false);
        }
    });

    // Filter
    $('.filter__btn').click(function () {
        $('.catalog__sidebar').addClass('catalog__sidebar--active')
        $('body').addClass('fixed-body')
    })

    $('.filter__close').click(function () {
        $('.catalog__sidebar').removeClass('catalog__sidebar--active')
        $('body').removeClass('fixed-body')
    })

    // Favorite
    $('.product-card__favorite').click(function () {
        $(this).toggleClass('favorite--active')
    })

    // Basket
    $('.basket-card__delete').click(function () {
        $(this).parents('.basket-card').remove()
    })

    // Calc
    function calc() {
        $('.calc').each(function () {
            let $calc = $(this);
            let $input = $calc.find('input');
            let $minus = $calc.find('.calc-minus');

            function checkValue() {
                let value = +$input.val();

                if (value === 0) {
                    $minus.addClass('null');
                } else {
                    $minus.removeClass('null');
                }
            }

            checkValue();

            $minus.click(function () {
                let a = +$input.val();

                if (a > 0) {
                    $input.val(a - 1);
                }

                checkValue();
            });

            $calc.find('.calc-plus').click(function () {
                let a = +$input.val();

                $input.val(a + 1);

                checkValue();
            });
        });
    }

    calc();

    // Select
    $('.select').niceSelect();

    // Fancybox
    Fancybox.bind("[data-fancybox]", {});

    // Nouislider
    const slider = document.getElementById('price-slider');

    const minInput = document.getElementById('price-min');
    const maxInput = document.getElementById('price-max');

    const MIN_PRICE = 0;
    const MAX_PRICE = 50;

    noUiSlider.create(slider, {
        start: [0, 50],

        connect: true,

        step: 1,

        range: {
            min: MIN_PRICE,
            max: MAX_PRICE
        }
    });

    slider.noUiSlider.on('update', function (values) {
        minInput.value = Math.round(values[0]);
        maxInput.value = Math.round(values[1]);
    });

    minInput.addEventListener('change', function () {
        let value = Number(this.value);

        if (this.value === '') {
            value = MIN_PRICE;
        }

        value = Math.max(MIN_PRICE, value);
        value = Math.min(value, Number(maxInput.value));

        slider.noUiSlider.set([value, null]);
    });

    maxInput.addEventListener('change', function () {
        let value = Number(this.value);

        if (this.value === '') {
            value = MAX_PRICE;
        }

        value = Math.min(MAX_PRICE, value);
        value = Math.max(value, Number(minInput.value));

        slider.noUiSlider.set([null, value]);
    });

})